
import matplotlib.pyplot as plt
from pathlib import Path as path
import numpy as np


# ============================================================
# DATA IMPORT
# ============================================================

# Resolve the directory containing this script.
folder = path(__file__).resolve().parent

# Locate the CSV generated by the bifurcation experiment.
csv_path = folder / "simulation.csv"

# Load the numerical data, skipping the CSV header.
data = np.loadtxt(
    csv_path,
    delimiter=",",
    skiprows=1
)


# Extract individual columns.
r_values = data[:, 0]
iterations = data[:, 1]
states = data[:, 2]


# Determine the number of unique parameter values.
unique_r = np.unique(r_values)


# ============================================================
# DATA VALIDATION
# ============================================================

print("=== ChaosLab Data Check ===")

print(f"Total data rows: {len(data)}")
print(f"Unique r values: {len(unique_r)}")

print(f"Minimum r: {r_values.min():.2f}")
print(f"Maximum r: {r_values.max():.2f}")

print(f"Minimum state: {states.min():.6f}")
print(f"Maximum state: {states.max():.6f}")


# ============================================================
# BIFURCATION DIAGRAM
# ============================================================

# Plot the long-term states against the control parameter.
# Each point represents a state reached during simulation.

plt.figure(figsize=(12, 7))

plt.scatter(
    r_values,
    states,
    s=10,
    marker=".",
    linewidths=0
)

plt.title("ChaosLab - Logistic Map Bifurcation Diagram")

plt.xlabel("Parameter r")
plt.ylabel("Long-term state x")

plt.xlim(2.5, 4.0)
plt.ylim(0.0, 1.0)

plt.grid(alpha=0.2)
plt.tight_layout()


# Display the resulting figure.
print("Attempting to display figure...")

plt.show()

print("Figure window closed.")
